import React, { useMemo } from 'react';
import { SearchInput, Select } from '@linm-soft-org/linm-web-common-components';
import { createStaticLookupSearchConfig } from '../../../components/search/createStaticLookupSearchConfig';
import styles from './PlanVoucherPage.module.css';

export interface ScheduleLookupItem {
  id: string;
  code: string;
  name: string;
}

/** Options: Last + ngày 1–28 (max = Feb-safe). */
export const MONTH_DAY_OPTIONS: ScheduleLookupItem[] = [
  { id: 'Last', code: 'Last', name: 'Ngày cuối tháng' },
  ...Array.from({ length: 28 }, (_, i) => {
    const d = String(i + 1);
    return { id: d, code: d, name: `Ngày ${i + 1}` };
  }),
];

const MONTH_OPTIONS = Array.from({ length: 12 }, (_, i) => {
  const m = i + 1;
  const code = String(m).padStart(2, '0');
  return { value: code, label: `Tháng ${m}` };
});

function daysInMonth(month: number): number {
  // Feb max 28 — parity rule lịch tháng (không 29/30/31)
  if (month === 2) return 28;
  if ([4, 6, 9, 11].includes(month)) return 30;
  return 31;
}

const monthDaySearchConfig = createStaticLookupSearchConfig<ScheduleLookupItem>({
  loadItems: () => MONTH_DAY_OPTIONS,
  getKey: i => i.id,
  getCode: i => i.code,
  getName: i => i.name,
  getFilterText: i => `${i.code} ${i.name}`,
  getSingleDisplay: i => i.name,
  codeHeaderLabel: 'Mã',
  nameHeaderLabel: 'Ngày',
  pageSize: 29,
});

export function MonthDayScheduleSearch({
  value,
  onChange,
  disabled,
  'data-testid': testId,
}: {
  value: string;
  onChange: (next: string) => void;
  disabled?: boolean;
  'data-testid'?: string;
}) {
  const selected = useMemo(
    () => (value ? MONTH_DAY_OPTIONS.find(o => o.id === value) ?? null : null),
    [value],
  );

  return (
    <SearchInput
      config={monthDaySearchConfig}
      className={styles.scheduleLookup}
      value={selected?.code ?? ''}
      primaryDisplay={selected?.name ?? ''}
      secondaryDisplay=""
      onChange={(item) => {
        const it = item as ScheduleLookupItem | null;
        if (it) onChange(it.code);
      }}
      onClear={() => onChange('')}
      showLabel={false}
      showSecondaryInput={false}
      placeholder="Chọn ngày trong tháng..."
      disabled={disabled}
      data-testid={testId}
    />
  );
}

/** Chọn tháng + ngày → `MM-DD` (không gõ tay). */
export function YearMonthDayPicker({
  value,
  onChange,
  disabled,
  'data-testid': testId,
}: {
  value: string;
  onChange: (mmDd: string) => void;
  disabled?: boolean;
  'data-testid'?: string;
}) {
  const match = /^(\d{2})-(\d{2})$/.exec((value || '').trim());
  const month = match?.[1] ?? '01';
  const day = match?.[2] ?? '01';
  const monthNum = parseInt(month, 10) || 1;
  const maxDay = daysInMonth(monthNum);
  const dayNum = Math.min(Math.max(parseInt(day, 10) || 1, 1), maxDay);
  const dayOptions = useMemo(
    () => Array.from({ length: maxDay }, (_, i) => {
      const d = i + 1;
      return { value: String(d).padStart(2, '0'), label: `Ngày ${d}` };
    }),
    [maxDay],
  );

  const emit = (m: string, d: string) => {
    const mn = parseInt(m, 10) || 1;
    const max = daysInMonth(mn);
    const dn = Math.min(Math.max(parseInt(d, 10) || 1, 1), max);
    onChange(`${String(mn).padStart(2, '0')}-${String(dn).padStart(2, '0')}`);
  };

  return (
    <div className={styles.yearMonthDayRow} data-testid={testId}>
      <Select
        value={month}
        onChange={(e: React.ChangeEvent<HTMLSelectElement>) => emit(e.target.value, day)}
        options={MONTH_OPTIONS}
        disabled={disabled}
        data-testid={testId ? `${testId}-month` : undefined}
      />
      <Select
        value={String(dayNum).padStart(2, '0')}
        onChange={(e: React.ChangeEvent<HTMLSelectElement>) => emit(month, e.target.value)}
        options={dayOptions}
        disabled={disabled}
        data-testid={testId ? `${testId}-day` : undefined}
      />
    </div>
  );
}
